const HTML="<!doctype html><html lang=\"vi\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"description\" content=\"Agency marketing AI của bạn. Đặt brief, phối hợp phòng ban và duyệt sản phẩm trong một không gian.\"><title>MKT Studio — Agency AI của bạn</title><link rel=\"stylesheet\" href=\"/assets/voxel-ui.css?v=6\"></head><body><div class=\"shell\"><header class=\"topbar\"><button class=\"logo\" data-nav=\"home\" aria-label=\"MKT Studio — Văn phòng\"><span class=\"cube-mark\" aria-hidden=\"true\"></span>MKT Studio</button><nav class=\"nav\" aria-label=\"Điều hướng chính\"><button data-nav=\"home\" class=\"active\">Văn phòng</button><button data-nav=\"orders\">Order</button><button data-nav=\"review\">Chờ duyệt</button><button data-nav=\"brand\">Thương hiệu</button></nav><div class=\"topbar-right\"><button class=\"connection\" id=\"connect\"><span class=\"dot\" id=\"connectionDot\"></span><span id=\"connectionLabel\">Kết nối AI</span></button><span class=\"avatar\" aria-label=\"Workspace cá nhân\">M</span></div></header><main class=\"main\"><span id=\"breadcrumb\" hidden>Tổng quan</span><div class=\"content\" id=\"app\"></div></main></div><div id=\"modalRoot\"></div><div id=\"toast\" role=\"status\" aria-live=\"polite\"></div><script src=\"/assets/voxel-office.js?v=6\"></script><script src=\"/assets/office-ui.js?v=6\"></script>\n<script>\nconst DEPTS={account:{name:'Account & Điều phối',icon:'↗',desc:'Tiếp nhận brief, chia đầu việc và quản lý bàn giao.',tag:'Đầu mối của mọi order'},strategy:{name:'Research & Strategy',icon:'⌕',desc:'Từ mục tiêu kinh doanh đến insight và chiến lược.',tag:'Insight · Campaign plan'},content:{name:'Content & Social',icon:'≋',desc:'Biến ý tưởng thành bài viết và kịch bản có thể dùng.',tag:'Caption · Script · Calendar'},creative:{name:'Creative & Design',icon:'✧',desc:'Concept, art direction và brief thiết kế chi tiết.',tag:'Concept · Visual brief'},performance:{name:'Performance',icon:'▥',desc:'Lập ngân sách, media plan và phương án thử nghiệm.',tag:'Media plan · A/B testing'},qa:{name:'Quality Assurance',icon:'✓',desc:'Đối chiếu brief, kiểm tra chất lượng trước khi bạn duyệt.',tag:'Kiểm tra đầu ra'}};\nObject.defineProperties(DEPTS,{account_work:{value:{...DEPTS.account,name:'Account · Sản phẩm bàn giao'}},qa_work:{value:{...DEPTS.qa,name:'QA · Báo cáo rà soát'}}});\nconst $=s=>document.querySelector(s);const esc=x=>String(x??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nlet storageOK=true;let state;try{state=JSON.parse(localStorage.getItem('mkt-studio-v1')||'null');}catch{storageOK=false;}if(!state||!Array.isArray(state.orders)||!state.brand)state={orders:[],brand:{name:'',audience:'',voice:'',facts:'',avoid:''},model:'gpt-5-mini'};\nlet route='home',activeId=null,activeTab='account',busy=false,apiKey='',serverConfigured=false,toastTimer,formDraft=null;\nfunction save(){try{localStorage.setItem('mkt-studio-v1',JSON.stringify(state));}catch{storageOK=false;toast('Không lưu được trên trình duyệt. Hãy xuất bản sao dữ liệu.');}}\nfunction toast(t){$('#toast').className='toast';$('#toast').textContent=t;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{$('#toast').className='';$('#toast').textContent='';},5500);}\nfunction status(o){return ({draft:'Bản nháp',clarify:'Cần bổ sung brief',running:'AI đang thực hiện',error:'Cần xử lý',review:'Chờ bạn duyệt',qa_failed:'QA cần kiểm tra',approved:'Đã duyệt',revision:'Đang sửa'})[o.status]||o.status;}\nfunction badge(o){return '<span class=\"badge '+(o.status==='approved'?'approved':['clarify','qa_failed'].includes(o.status)?'warn':o.status==='error'?'error':'')+'\">'+esc(status(o))+'</span>';}\nfunction current(){return state.orders.find(o=>o.id===activeId);}function nav(r){captureQuickDrafts();if(route==='new')captureForm();if(r==='home'&&route!=='home')selectedRoom=null;route=r;render();window.scrollTo({top:0,behavior:'smooth'});}\nfunction updateConnection(){$('#connectionDot').className='dot'+(apiKey||serverConfigured?' ok':'');$('#connectionLabel').textContent=apiKey||serverConfigured?(serverConfigured?'AI do máy chủ cung cấp':'Đã nhập key · Chưa xác minh'):'Kết nối AI';}\nfunction cards(){return '<div class=\"dept-grid\">'+Object.entries(DEPTS).map(([k,d])=>'<button class=\"dept\" data-dept=\"'+k+'\"><div class=\"dept-top\"><span class=\"dept-icon\">'+d.icon+'</span><span class=\"pill\">AI chuyên trách</span></div><h3>'+d.name+'</h3><p>'+d.desc+'</p><div class=\"dept-foot\"><span>'+d.tag+'</span><b>↗</b></div></button>').join('')+'</div>';}\nfunction heading(title,sub,button=''){return '<div class=\"pageheading\"><div><span class=\"eyebrow\">YOUR AI MARKETING AGENCY</span><h1>'+title+'</h1><p class=\"muted\">'+sub+'</p></div>'+button+'</div>';}\nfunction newButton(){return '<button class=\"btn primary\" data-new>＋ Tạo order mới</button>';}\nfunction rows(orders){if(!orders.length)return '<div class=\"empty\"><div class=\"big\">▤</div><h3>Chưa có order nào ở đây</h3><p class=\"muted\">Bắt đầu từ một brief. Agency AI sẽ tiếp nhận phần còn lại.</p><button class=\"btn primary small\" data-new>Tạo order đầu tiên ↗</button></div>';return orders.map(o=>'<div class=\"order-row\" tabindex=\"0\" role=\"button\" data-order=\"'+o.id+'\"><div><h3>'+esc(o.title)+'</h3><small>'+esc(o.id.slice(0,8).toUpperCase())+' · '+(o.mode==='full'?'Agency trọn gói':esc(DEPTS[o.department]?.name))+' · '+new Date(o.created).toLocaleDateString('vi-VN')+'</small></div><div>'+badge(o)+'</div></div>').join('');}\nfunction home(){return officeHome();}\nfunction form(){const d=formDraft||{mode:'full',department:'content',title:'',brief:'',deadline:'',budget:'',deliverables:''};return heading('Agency sẵn sàng nhận brief.','Mô tả điều bạn cần. Account AI sẽ làm rõ và phân công.')+'<form id=\"orderForm\"><div class=\"segmented\"><button type=\"button\" data-mode=\"full\" class=\"'+(d.mode==='full'?'selected':'')+'\"><b>✳ Agency trọn gói</b><small>Account tự chọn phòng ban theo brief</small></button><button type=\"button\" data-mode=\"single\" class=\"'+(d.mode==='single'?'selected':'')+'\"><b>↗ Order một phòng ban</b><small>Giao đúng một đầu việc chuyên môn</small></button></div><div class=\"form-grid\"><div class=\"panel\"><div class=\"field\"><label for=\"title\">Tên order *</label><input id=\"title\" name=\"title\" maxlength=\"150\" required value=\"'+esc(d.title)+'\" placeholder=\"VD: Nội dung ra mắt bộ sưu tập túi tháng 11\"></div>'+(d.mode==='single'?'<div class=\"field\"><label for=\"department\">Phòng ban thực hiện</label><select id=\"department\" name=\"department\">'+Object.entries(DEPTS).map(([k,v])=>'<option value=\"'+k+'\" '+(d.department===k?'selected':'')+'>'+v.name+'</option>').join('')+'</select></div>':'')+'<div class=\"field\"><label for=\"brief\">Brief của bạn *</label><textarea id=\"brief\" name=\"brief\" required maxlength=\"12000\" style=\"min-height:210px\" placeholder=\"Sản phẩm/dịch vụ là gì? Bạn muốn đạt mục tiêu nào? Khách hàng là ai? Đăng trên kênh nào? Có thông tin nào phải dùng hoặc cần tránh?\">'+esc(d.brief)+'</textarea></div><div class=\"field\"><label for=\"deliverables\">Đầu ra cần nhận *</label><textarea id=\"deliverables\" name=\"deliverables\" required maxlength=\"4000\" placeholder=\"VD: 5 caption Facebook, 2 kịch bản TikTok 30 giây và brief thiết kế cho 3 visual\">'+esc(d.deliverables)+'</textarea></div></div><div><div class=\"panel\"><h3>Thông tin để làm đúng ngay từ đầu</h3><div class=\"field\"><label for=\"deadline\">Deadline mong muốn</label><input id=\"deadline\" name=\"deadline\" type=\"date\" value=\"'+esc(d.deadline)+'\"><small>Được ghi vào brief; chưa có lịch tự chạy khi đóng web.</small></div><div class=\"field\"><label for=\"budget\">Ngân sách marketing</label><input id=\"budget\" name=\"budget\" maxlength=\"100\" value=\"'+esc(d.budget)+'\" placeholder=\"VD: 20.000.000 VNĐ / tháng\"><small>Ngân sách campaign, không phải phí gọi AI.</small></div><div class=\"hint\">◇ Thương hiệu: <b>'+esc(state.brand.name||'Chưa thiết lập')+'</b><br>Tài liệu thương hiệu sẽ được gửi kèm brief cho các phòng ban.</div><div class=\"field\"><label for=\"referenceFile\">Thêm tài liệu tham khảo (.txt, .md)</label><input class=\"file-input\" id=\"referenceFile\" type=\"file\" accept=\".txt,.md,text/plain,text/markdown\"><small>Nội dung được thêm vào brief; tối đa 25 KB.</small></div></div><div class=\"hint warning\">AI tạo nội dung, kế hoạch và creative brief. Bản này chưa tạo file ảnh/video, chưa đăng bài hoặc chạy ads. Mọi dữ kiện chưa có nguồn phải được kiểm chứng.</div></div></div><div class=\"form-actions\"><button type=\"button\" class=\"btn\" data-route=\"home\">Quay lại</button><button type=\"submit\" class=\"btn primary\" '+(busy?'disabled':'')+'>Gửi order cho agency ↗</button></div></form>';}\nfunction brand(){const b=state.brand;return heading('Một thương hiệu. Một tiếng nói.','Lưu bối cảnh để mọi phòng ban cùng làm theo.')+'<div class=\"form-grid\"><form class=\"panel\" id=\"brandForm\">'+[['name','Tên thương hiệu','VD: HAPAS'],['audience','Khách hàng mục tiêu','Độ tuổi, nhu cầu, thị trường, ngôn ngữ'],['voice','Giọng điệu & phong cách','VD: Gần gũi, tinh tế, tự tin; xưng hô bạn – mình'],['facts','Thông tin đã xác thực','Sản phẩm, giá, điểm khác biệt, chính sách và các nguồn bạn cung cấp'],['avoid','Điều cần tránh','Từ ngữ cấm, claim chưa được xác thực, đối thủ không nhắc tới']].map(([k,l,p])=>'<div class=\"field\"><label for=\"brand-'+k+'\">'+l+'</label>'+(k==='name'?'<input id=\"brand-'+k+'\" name=\"'+k+'\" maxlength=\"150\" value=\"'+esc(b[k])+'\" placeholder=\"'+p+'\">':'<textarea id=\"brand-'+k+'\" name=\"'+k+'\" maxlength=\"6000\" placeholder=\"'+p+'\">'+esc(b[k])+'</textarea>')+'</div>').join('')+'<button class=\"btn primary\">Lưu thương hiệu</button></form><div><div class=\"brand-preview\"><span class=\"eyebrow\" style=\"color:#c1d59d\">BRAND MEMORY</span><h2 style=\"margin-top:15px\">'+esc(b.name||'Thương hiệu của bạn')+'</h2><p>'+esc(b.voice||'Tạo bối cảnh chung cho cả agency.')+'</p></div><div class=\"hint\">Dữ liệu được lưu trên trình duyệt này. Hãy xuất bản sao để chuyển máy hoặc phòng mất dữ liệu. API key không nằm trong bản sao.</div><div class=\"panel\"><h3>Sao lưu workspace</h3><p class=\"muted\">Bao gồm thương hiệu, brief, đầu ra và lịch sử duyệt.</p><button type=\"button\" class=\"btn small\" id=\"backup\">↓ Xuất dữ liệu JSON</button><div class=\"field\" style=\"margin-top:18px\"><label for=\"importFile\">Khôi phục bản sao JSON</label><input id=\"importFile\" type=\"file\" accept=\".json\"><small>Order trùng ID được giữ nguyên; chỉ thêm order chưa có.</small></div></div></div></div>';}\nfunction formatJSON(role,raw){try{const d=JSON.parse(raw);if(role==='account')return 'BRIEF ĐÃ TIẾP NHẬN\\n\\n'+d.summary+'\\n\\nPHÒNG BAN THỰC HIỆN\\n'+(d.departments||[]).map(k=>'• '+(DEPTS[k]?.name||k)).join('\\n')+'\\n\\nTIÊU CHÍ NGHIỆM THU\\n'+(d.acceptance||[]).map(x=>'• '+x).join('\\n')+(d.needs_clarification?'\\n\\nCẦN BẠN BỔ SUNG\\n'+d.questions.map((q,i)=>(i+1)+'. '+q).join('\\n'):'');if(role==='qa')return (d.passed?'✓ QA đạt':'△ QA cần kiểm tra')+'\\n\\n'+d.summary+'\\n\\n'+(d.checklist||[]).map(x=>(x.passed?'✓ ':'✕ ')+x.criterion).join('\\n')+'\\n\\n'+(d.issues||[]).map(x=>'['+(DEPTS[x.department]?.name||x.department)+'] '+x.issue+'\\nCần sửa: '+x.fix).join('\\n\\n');}catch{}return raw;}\nfunction detail(){const o=current();if(!o){route='orders';return rows(state.orders);}const pipeline=o.pipeline||['account'];const output=o.outputs[activeTab];const versions=(o.history||[]).filter(v=>v.role===activeTab);return heading(esc(o.title),'Order '+esc(o.id.slice(0,8).toUpperCase())+' · '+new Date(o.created).toLocaleString('vi-VN'),'<button class=\"btn small\" id=\"export\">↓ Xuất bàn giao</button>')+'<div class=\"meta\">'+badge(o)+'<span>'+esc(o.mode==='full'?'Agency trọn gói':DEPTS[o.department]?.name)+'</span><span>Deadline: '+esc(o.deadline||'Chưa đặt')+'</span><span>'+o.calls+' lượt gọi AI</span></div>'+(o.status==='draft'?'<div class=\"hint\">Order đã lưu. <button class=\"btn primary small\" id=\"startDraft\">'+(apiKey||serverConfigured?'Chạy order':'Kết nối AI & chạy order')+'</button></div>':'')+'<div class=\"workflow\">'+pipeline.map(k=>'<span class=\"step '+(o.runningRole===k&&busy?'running busy':o.outputs[k]?'done':'')+'\">'+(o.outputs[k]?'✓ ':'')+DEPTS[k].name+'</span>').join('')+'</div>'+(o.error?'<div class=\"error-box\" role=\"alert\">'+esc(o.error)+'<br><button class=\"btn small\" id=\"retry\" '+(busy?'disabled':'')+' style=\"margin-top:10px\">Tiếp tục từ bước lỗi</button></div>':'')+(o.status==='clarify'?'<div class=\"panel\" style=\"margin-bottom:18px\"><h3>Account cần bạn bổ sung</h3><p>'+esc((o.questions||[]).join('\\n'))+'</p><textarea id=\"clarification\" maxlength=\"6000\" placeholder=\"Trả lời các câu hỏi để agency tiếp tục\"></textarea><button class=\"btn primary small\" id=\"clarify\" style=\"margin-top:12px\" '+(busy?'disabled':'')+'>Bổ sung và tiếp tục</button></div>':'')+'<div class=\"detail-grid\"><div class=\"tasknav\"><button data-task=\"brief\" class=\"'+(activeTab==='brief'?'selected':'')+'\">▤ Brief gốc<small>Yêu cầu & tài liệu thương hiệu</small></button>'+pipeline.map(k=>'<button data-task=\"'+k+'\" class=\"'+(activeTab===k?'selected':'')+'\">'+DEPTS[k].icon+' '+DEPTS[k].name+'<small>'+(o.runningRole===k&&busy?'Đang thực hiện…':o.outputs[k]?'Đã có kết quả':'Chờ bàn giao')+'</small></button>').join('')+'</div><div class=\"panel\"><div class=\"output-title\"><h2>'+esc(activeTab==='brief'?'Brief & bối cảnh':DEPTS[activeTab]?.name||'Đầu ra')+'</h2>'+(output?'<button class=\"btn small\" id=\"copy\">Sao chép</button>':'')+'</div><pre class=\"output\" id=\"output\">'+esc(activeTab==='brief'?briefContext(o):output?formatJSON(activeTab,output):busy&&o.runningRole===activeTab?'AI đang thực hiện. Giữ trang mở để nhận và chuyển tiếp kết quả.':'Kết quả sẽ xuất hiện sau khi phòng ban thực hiện.')+'</pre>'+(versions.length?'<details><summary class=\"muted\">'+versions.length+' phiên bản trước</summary>'+versions.map(v=>'<details style=\"margin:10px 0\"><summary>'+new Date(v.at).toLocaleString('vi-VN')+'</summary><pre class=\"output\">'+esc(formatJSON(v.role,v.output))+'</pre></details>').join('')+'</details>':'')+(busy?'<div class=\"progress-note busy\">● Agency đang xử lý '+esc(DEPTS[o.runningRole]?.name||'order')+'. Các kết quả đã xong được lưu tự động.</div>':'')+(o.outputs.qa&&!busy?'<div class=\"review\"><h3>Quyết định cuối cùng thuộc về bạn</h3>'+(o.status==='qa_failed'?'<div class=\"hint warning\">QA còn phát hiện vấn đề. Dùng “Sửa theo QA” để các phòng ban liên quan xử lý trước khi duyệt.</div>':'')+(o.status==='approved'?'<div class=\"hint\">✓ Đã được bạn duyệt lúc '+new Date(o.approvedAt).toLocaleString('vi-VN')+'.</div>':'')+'<textarea id=\"feedback\" maxlength=\"5000\" placeholder=\"VD: Giữ concept, viết lại caption theo giọng gần gũi hơn; bỏ claim chưa có nguồn.\"></textarea><div class=\"review-actions\"><button class=\"btn primary small\" id=\"approve\" '+(o.status!=='review'?'disabled':'')+'>✓ Duyệt đầu ra</button><button class=\"btn small\" id=\"revise\">Yêu cầu sửa</button>'+(o.status==='qa_failed'?'<button class=\"btn small\" id=\"fixqa\">Sửa theo QA</button>':'')+'</div><p class=\"muted\" style=\"font-size:11px\">Duyệt ghi nhận quyết định của bạn; không tự đăng bài hay chi tiền quảng cáo.</p></div>':'')+'</div></div>';}\nfunction render(){captureQuickDrafts();officeScene?.destroy();officeScene=null;document.querySelectorAll('[data-nav]').forEach(n=>n.classList.toggle('active',n.dataset.nav===route));$('#breadcrumb').textContent=({home:'Tổng quan',orders:'Order của tôi',departments:'Phòng ban AI',review:'Chờ duyệt',brand:'Thương hiệu',new:'Tạo order',detail:'Chi tiết order'})[route];$('#app').innerHTML=(route==='home'?home():route==='new'?form():route==='brand'?brand():route==='departments'?heading('Đúng chuyên môn. Đúng đầu việc.','Chọn phòng để giao việc riêng. Mọi đầu ra đều được kiểm tra trước khi bạn duyệt.')+cards():route==='detail'?detail():heading(route==='review'?'Đầu ra đang chờ bạn.':'Mọi order, cùng một nơi.',route==='review'?'Xem sản phẩm, phản hồi và quyết định duyệt.':'Từ brief đầu tiên đến phiên bản được phê duyệt.',newButton())+rows(route==='review'?state.orders.filter(o=>['review','qa_failed'].includes(o.status)):state.orders))+'<footer><span>MKT Studio · Agency AI, bạn giữ quyền duyệt.</span><span>'+(storageOK?'Dữ liệu lưu trên trình duyệt này · Xuất bản sao định kỳ':'⚠ Không lưu được dữ liệu · Hãy xuất bản sao')+'</span></footer>';bind();bindOffice();}\nfunction captureForm(){if(!$('#orderForm'))return;const values=Object.fromEntries(new FormData($('#orderForm')));formDraft={...formDraft,...values};}\nfunction begin(dept){if(busy){toast('Hãy chờ order hiện tại hoàn tất.');return;}formDraft={mode:dept?'single':'full',department:dept||'content',title:'',brief:'',deliverables:'',deadline:'',budget:''};nav('new');}\nfunction bind(){document.querySelectorAll('[data-new]').forEach(n=>n.onclick=()=>begin());document.querySelectorAll('[data-route]').forEach(n=>n.onclick=()=>nav(n.dataset.route));document.querySelectorAll('[data-dept]').forEach(n=>n.onclick=()=>{openRoom(n.dataset.dept);});document.querySelectorAll('[data-order]').forEach(n=>{const go=()=>{activeId=n.dataset.order;activeTab='account';nav('detail');};n.onclick=go;n.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go();}};});document.querySelectorAll('[data-mode]').forEach(n=>n.onclick=()=>{captureForm();formDraft.mode=n.dataset.mode;render();});document.querySelectorAll('[data-task]').forEach(n=>n.onclick=()=>{activeTab=n.dataset.task;render();});\nif($('#orderForm'))$('#orderForm').onsubmit=async e=>{e.preventDefault();if(busy)return;captureForm();const v=formDraft;let reference='';const f=$('#referenceFile').files[0];if(f){if(f.size>25000||!(/\\.(txt|md)$/i.test(f.name))){toast('Chỉ nhận .txt/.md tối đa 25 KB.');return;}reference=await f.text();}const o={...v,id:orderId(),created:new Date().toISOString(),brand:{...state.brand},reference,status:'draft',outputs:{},history:[],pipeline:['account'],calls:0,error:null};state.orders.unshift(o);save();activeId=o.id;activeTab='account';nav('detail');await execute(o);};\nif($('#brandForm'))$('#brandForm').onsubmit=e=>{e.preventDefault();state.brand=Object.fromEntries(new FormData(e.target));save();toast('Đã lưu bối cảnh thương hiệu. Áp dụng cho order mới.');render();};\nif($('#startDraft'))$('#startDraft').onclick=()=>execute(current());if($('#retry'))$('#retry').onclick=()=>execute(current());if($('#clarify'))$('#clarify').onclick=()=>{const t=$('#clarification').value.trim();if(!t){toast('Hãy bổ sung câu trả lời.');return;}const o=current();o.clarifications=(o.clarifications||'')+'\\n'+t;archive(o,'account');o.outputs={};o.pipeline=['account'];o.status='draft';save();execute(o);};\nif($('#copy'))$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(formatJSON(activeTab,current().outputs[activeTab]));toast('Đã sao chép.');}catch{toast('Không truy cập được clipboard. Bạn có thể chọn nội dung và sao chép.');}};\nif($('#approve'))$('#approve').onclick=()=>{const o=current();if(o.status!=='review')return;o.status='approved';o.approvedAt=new Date().toISOString();save();render();toast('Đã duyệt. Sản phẩm sẵn sàng để bạn sử dụng.');};\nif($('#revise'))$('#revise').onclick=()=>{const t=$('#feedback').value.trim();if(!t){toast('Nhập phản hồi để AI biết cần sửa gì.');return;}revise(current(),t,false);};if($('#fixqa'))$('#fixqa').onclick=()=>revise(current(),'Xử lý tất cả lỗi QA và kiểm tra lại. '+($('#feedback')?.value||''),true);\nif($('#export'))$('#export').onclick=()=>exportOrder(current());if($('#backup'))$('#backup').onclick=()=>download('mkt-studio-backup.json',JSON.stringify(state,null,2),'application/json');if($('#importFile'))$('#importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5000000)throw Error();const b=JSON.parse(await f.text());if(!Array.isArray(b.orders)||!b.brand||b.orders.some(o=>!o.id||!o.title||!o.outputs||!Array.isArray(o.pipeline)||o.pipeline.some(k=>!DEPTS[k])))throw Error();const existing=new Set(state.orders.map(o=>o.id));const newOrders=b.orders.filter(o=>!existing.has(o.id)).map(o=>({...o,status:['running','revision'].includes(o.status)?'error':o.status,error:['running','revision'].includes(o.status)?'Phiên trước bị ngắt. Bấm Tiếp tục để chạy tiếp.':o.error}));state.orders.push(...newOrders);if(!state.brand.name)state.brand=b.brand;save();toast('Đã khôi phục '+newOrders.length+' order mới.');render();}catch{toast('Bản sao không hợp lệ hoặc quá lớn (tối đa 5 MB).');}};\n}\nfunction briefContext(o){return 'ORDER: '+o.title+'\\nLOẠI: '+(o.mode==='full'?'Trọn gói':'Phòng ban: '+o.department)+'\\nBRIEF:\\n'+o.brief+'\\nDELIVERABLES:\\n'+o.deliverables+'\\nDEADLINE: '+(o.deadline||'Chưa đặt')+'\\nNGÂN SÁCH: '+(o.budget||'Chưa đặt')+'\\nTHƯƠNG HIỆU:\\n'+JSON.stringify(o.brand)+'\\nTÀI LIỆU THAM KHẢO:\\n'+(o.reference||'Không có')+'\\nBỔ SUNG TỪ KHÁCH:\\n'+(o.clarifications||'Không có')+'\\nPHẢN HỒI SỬA:\\n'+(o.feedback||'Không có');}\nfunction context(o){return briefContext(o)+'\\n\\nKẾT QUẢ BÀN GIAO:\\n'+Object.entries(o.outputs).map(([k,v])=>'--- '+DEPTS[k].name+' ---\\n'+v).join('\\n\\n');}\nfunction archive(o,k){if(o.outputs[k])o.history.push({role:k,output:o.outputs[k],at:new Date().toISOString()});delete o.outputs[k];}\nasync function generate(o,role){o.runningRole=role;if(activeId===o.id){activeTab=role;render();}save();const response=await fetch('/api/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({role,context:context(o),model:state.model,apiKey})});let body;try{body=await response.json();}catch{throw Error('Máy chủ chưa trả kết quả hợp lệ. Hãy thử lại.');}if(!response.ok)throw Error(body.error||'Không tạo được đầu ra.');$('#connectionLabel').textContent='AI đã xác minh';o.calls++;let result=body.output;if(role==='account'){let p;try{p=JSON.parse(result);}catch{throw Error('Account trả định dạng chưa hợp lệ. Bấm thử lại.');}if(typeof p.needs_clarification!=='boolean'||typeof p.summary!=='string'||!Array.isArray(p.departments)||!Array.isArray(p.acceptance)||!Array.isArray(p.questions))throw Error('Account thiếu thông tin điều phối. Bấm thử lại.');if(p.needs_clarification){o.questions=p.questions;o.status='clarify';}else{let depts=o.mode==='single'?[workRole(o.department)]:p.departments.filter(k=>['strategy','content','creative','performance'].includes(k));depts=[...new Set(depts)];if(!depts.length)throw Error('Account chưa chọn phòng ban. Hãy bổ sung brief.');p.departments=depts;o.pipeline=['account',...depts,'qa'];}result=JSON.stringify(p);}if(role==='qa'){let p;try{p=JSON.parse(result);}catch{throw Error('QA trả định dạng chưa hợp lệ. Bấm thử lại.');}if(typeof p.passed!=='boolean'||!Array.isArray(p.issues)||!Array.isArray(p.checklist)||typeof p.summary!=='string')throw Error('QA thiếu kết quả kiểm tra. Bấm thử lại.');o.qaPassed=p.passed&&p.issues.length===0&&p.checklist.length>0&&p.checklist.every(c=>c.passed===true);}o.outputs[role]=result;save();}\nasync function execute(o){if(busy)return;if(!apiKey&&!serverConfigured){o.status='draft';save();render();openConnection();toast('Kết nối AI rồi bấm Chạy order trong cửa sổ này.');return;}busy=true;o.error=null;o.status='running';render();try{if(!o.outputs.account){await generate(o,'account');if(o.status==='clarify')return;}for(const role of o.pipeline.slice(1)){if(!o.outputs[role])await generate(o,role);}o.status=o.qaPassed?'review':'qa_failed';toast(o.qaPassed?'Agency đã bàn giao. Mời bạn duyệt.':'QA đã tìm thấy điểm cần sửa. Xem kết quả kiểm tra.');}catch(e){o.status='error';o.error=e.message;}finally{busy=false;o.runningRole=null;save();if(activeId===o.id)render();}}\nfunction revise(o,feedback,qaOnly){if(busy)return;o.feedback=(o.feedback||'')+'\\n'+feedback;o.revisionCount=(o.revisionCount||0)+1;let start=1;if(qaOnly){try{const issues=JSON.parse(o.outputs.qa).issues||[];const indices=issues.map(x=>o.pipeline.indexOf(x.department)).filter(i=>i>0);if(indices.length)start=Math.min(...indices);}catch{}}for(const k of o.pipeline.slice(start))archive(o,k);o.status='revision';o.approvedAt=null;save();execute(o);}\nfunction download(name,text,type){const blob=new Blob([text],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500);}\nfunction exportOrder(o){download('MKT-'+o.id.slice(0,8)+'.md','# '+o.title+'\\n\\nTrạng thái: '+status(o)+'\\n\\n## Brief\\n\\n'+briefContext(o)+'\\n\\n'+o.pipeline.filter(k=>o.outputs[k]).map(k=>'## '+DEPTS[k].name+'\\n\\n'+formatJSON(k,o.outputs[k])).join('\\n\\n')+(o.approvedAt?'\\n\\nĐược khách duyệt: '+o.approvedAt:''),'text/markdown;charset=utf-8');}\nfunction openConnection(){$('#modalRoot').innerHTML='<div class=\"modal-backdrop\"><section class=\"modal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"modalTitle\"><div class=\"modal-head\"><h2 id=\"modalTitle\">Kết nối đội ngũ AI</h2><button class=\"close\" id=\"closeModal\" aria-label=\"Đóng\">×</button></div><p class=\"muted\">Dùng OpenAI API để các phòng ban thực hiện yêu cầu thật.</p><form id=\"connectionForm\"><div class=\"field\"><label for=\"key\">OpenAI API key</label><input id=\"key\" type=\"password\" autocomplete=\"off\" placeholder=\"sk-…\" value=\"'+esc(apiKey)+'\"><small>Key chỉ giữ trong bộ nhớ tab, không lưu vào workspace hay GitHub. Key được gửi qua máy chủ của app tới OpenAI khi bạn chạy order.</small></div><div class=\"field\"><label for=\"model\">Model ID</label><input id=\"model\" required maxlength=\"100\" value=\"'+esc(state.model)+'\"><small>Model phải được tài khoản API của bạn cấp quyền sử dụng.</small></div><div class=\"hint warning\">Mỗi phòng ban là một lượt gọi API có tính phí. Order trọn gói tối đa 6 lượt mỗi vòng. Đóng hoặc tải lại tab sẽ ngắt luồng; có thể tiếp tục từ kết quả đã lưu.</div><p style=\"font-size:12px\"><a href=\"https://platform.openai.com/api-keys\" target=\"_blank\" rel=\"noopener noreferrer\">Tạo API key tại OpenAI ↗</a></p><div class=\"form-actions\"><button class=\"btn\" type=\"button\" id=\"forgetKey\">Xóa key khỏi phiên</button><button class=\"btn primary\" type=\"submit\">'+(current()?.status==='draft'?'Kết nối & chạy order':'Lưu kết nối')+'</button></div></form></section></div>';$('#closeModal').onclick=()=>$('#modalRoot').innerHTML='';$('#forgetKey').onclick=()=>{apiKey='';updateConnection();$('#key').value='';toast('Đã xóa key khỏi bộ nhớ phiên.');};$('#connectionForm').onsubmit=e=>{e.preventDefault();const key=$('#key').value.trim();if(!key&&!serverConfigured){toast('Nhập API key để chạy AI.');return;}apiKey=key;state.model=$('#model').value.trim();save();updateConnection();$('#modalRoot').innerHTML='';toast('Đã lưu kết nối. Key được kiểm tra khi chạy order.');if(current()?.status==='draft')execute(current());};$('#key').focus();}\ndocument.querySelectorAll('[data-nav]').forEach(n=>n.onclick=()=>nav(n.dataset.nav));$('#connect').onclick=openConnection;document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#modalRoot').innerHTML='';});window.addEventListener('beforeunload',e=>{if(busy){e.preventDefault();e.returnValue='';}});\nfor(const o of state.orders){if(['running','revision'].includes(o.status)){o.status='error';o.runningRole=null;o.error='Phiên trước bị ngắt. Bấm Tiếp tục từ bước lỗi để chạy tiếp.';}}save();render();fetch('/api/status').then(r=>r.json()).then(s=>{serverConfigured=!!s.configured;updateConnection();}).catch(()=>{});\n</script></body></html>\n";
const OFFICE_JS="/* Dependency-free, orthographic voxel office. Render on interaction or resize only. */\n(() => {\n  const ROOMS = [\n    {id:'account',name:'Account',x:-7,z:-3.7,color:'#6587df'},\n    {id:'strategy',name:'Strategy',x:0,z:-3.7,color:'#48a69c'},\n    {id:'content',name:'Content',x:7,z:-3.7,color:'#9265ed'},\n    {id:'creative',name:'Creative',x:-7,z:3.2,color:'#e9b953'},\n    {id:'performance',name:'Performance',x:0,z:3.2,color:'#5e9edc'},\n    {id:'qa',name:'QA',x:7,z:3.2,color:'#e68da9'}\n  ];\n  const tint=(hex,n)=>'#'+hex.slice(1).match(/../g).map(x=>Math.max(0,Math.min(255,Math.round(parseInt(x,16)*n))).toString(16).padStart(2,'0')).join('');\n  class VoxelOffice {\n    constructor(host,{onSelect,selected=null,counts={}}={}) {\n      this.host=host;this.onSelect=onSelect;this.selected=selected;this.counts=counts;this.hover=null;this.boxes=[];\n      this.canvas=document.createElement('canvas');this.canvas.setAttribute('aria-hidden','true');\n      this.canvas.className='voxel-canvas';host.append(this.canvas);this.ctx=this.canvas.getContext('2d');\n      this.labels=document.createElement('div');this.labels.className='voxel-labels';host.append(this.labels);\n      this.buttons=ROOMS.map(room=>{\n        const button=document.createElement('button');button.type='button';button.className='room-label';\n        button.dataset.voxelRoom=room.id;button.style.setProperty('--room-color',room.color);\n        button.setAttribute('aria-controls','roomDrawer');button.setAttribute('aria-expanded',String(selected===room.id));\n        button.innerHTML='<span>'+room.name+'</span><small>'+((counts[room.id]||0)?counts[room.id]+' order đang mở':'Giao việc ↗')+'</small>';\n        button.onclick=()=>onSelect?.(room.id);this.labels.append(button);return button;\n      });\n      if(!this.ctx){host.classList.add('voxel-unavailable');return;}\n      this.build();\n      this.pointer=e=>{const r=this.canvas.getBoundingClientRect();const hit=this.hit(e.clientX-r.left,e.clientY-r.top);if(hit!==this.hover){this.hover=hit;this.draw();this.canvas.style.cursor=hit?'pointer':'default';}};\n      this.leave=()=>{if(this.hover){this.hover=null;this.draw();}};\n      this.click=e=>{const r=this.canvas.getBoundingClientRect();const hit=this.hit(e.clientX-r.left,e.clientY-r.top);if(hit)onSelect?.(hit);};\n      this.canvas.addEventListener('pointermove',this.pointer);this.canvas.addEventListener('pointerleave',this.leave);this.canvas.addEventListener('click',this.click);\n      this.observer=new ResizeObserver(()=>this.resize());this.observer.observe(host);this.resize();\n    }\n    box(x,y,z,w,h,d,color,layer=1,room=null){this.boxes.push({x,y,z,w,h,d,color,layer,room});}\n    plant(x,z,size=1){\n      this.box(x,.22,z,.48,.44,.48,'#bda6dd');this.box(x,.75,z,.12,.8,.12,'#92765b');\n      [[0,1.45,0,.56],[.3,1.15,.13,.45],[-.26,1.1,-.15,.5],[.08,1.8,.04,.4]].forEach(([dx,y,dz,s],i)=>this.box(x+dx*size,y*size,z+dz*size,s*size,s*size,s*size,['#91bb66','#709c57','#a7ca7b','#87ae57'][i]));\n    }\n    person(x,z,shirt,standing=false){\n      const y=standing?.35:.44;\n      this.box(x-.14,y,z,.19,.6,.26,'#4c4a69');this.box(x+.14,y,z,.19,.6,.26,'#4c4a69');\n      this.box(x,y+.55,z,.64,.62,.4,shirt);this.box(x-.4,y+.5,z-.08,.16,.45,.2,shirt);this.box(x+.4,y+.5,z-.08,.16,.45,.2,shirt);\n      this.box(x,y+1.12,z,.49,.48,.44,'#d8ab87');this.box(x,y+1.35,z+.02,.54,.19,.5,'#494050');\n      this.box(x,y+1.15,z+.22,.54,.4,.12,'#494050');this.box(x-.18,y+1.22,z-.21,.16,.18,.13,'#494050');\n      if(!standing){this.box(x,.55,z+.28,.78,.85,.18,shirt);this.box(x,.25,z,.85,.12,.65,'#534873');}\n    }\n    desk(x,z,accent){\n      this.box(x,1.05,z,2.2,.18,1.25,'#e6c895');\n      [-.86,.86].forEach(dx=>[-.43,.43].forEach(dz=>this.box(x+dx,.5,z+dz,.12,1,.12,'#c1accf')));\n      this.box(x,1.6,z-.25,.98,.7,.13,'#5d597d');this.box(x,1.6,z-.17,.84,.55,.02,'#d8e1fc');\n      this.box(x,1.25,z-.25,.1,.25,.1,'#66617b');this.box(x,1.12,z+.28,.7,.03,.3,'#c8c4e2');\n      this.box(x+.72,1.3,z+.1,.19,.35,.19,accent);\n      this.box(x-.16,1.63,z-.15,.38,.08,.02,accent);this.box(x-.1,1.48,z-.15,.52,.035,.02,'#989ec3');\n    }\n    build(){\n      const b=(...args)=>this.box(...args);\n      b(0,-.35,.4,22,.7,18.8,'#beb3d9',0);b(0,.01,.4,21.7,.03,18.5,'#e6e1f1',0);\n      for(let x=-10;x<=10;x++)for(let z=-8;z<=9;z++)b(x,.03,z,.96,.025,.96,(x+z)%2?'#ede8f6':'#e8e2f2',0);\n      b(0,-.14,10.1,5,.3,1,'#d7cfe6',0);b(0,-.3,10.7,5.7,.3,.5,'#c5bad9',0);\n      ROOMS.forEach(room=>{\n        const {x,z,color,id}=room;\n        b(x,.08,z,6.35,.08,5.7,'#f4ecdc',.2,id);\n        for(let n=-3;n<=3;n++)b(x+n*.88,.13,z,.85,.015,5.55,n%2?'#eadbc3':'#eee0c9',.2);\n        b(x,1.25,z-2.8,6.4,2.5,.2,'#cbbde4');b(x-3.15,.62,z,.18,1.25,5.6,'#d6cbea');b(x+3.15,.62,z,.18,1.25,5.6,'#c3b2dd');\n        for(let n=-3;n<=3;n++)b(x+n,.24,z-2.96,.93,.45,.15,'#b8a3d2');\n        b(x,1.65,z-2.65,3.15,1.05,.12,'#f8f4ef');\n        for(let c=0;c<4;c++)for(let r=0;r<2;r++)b(x-1.15+c*.72,1.4+r*.45,z-2.57,.4,.24,.03,[color,'#edcb87','#d4c2ed'][((c+r)%3)]);\n        b(x,2.55,z-2.76,2.8,.22,.24,color);\n        if(id==='strategy'||id==='account'){\n          b(x,.98,z,3.5,.2,1.5,'#e3c18d');[-1.4,1.4].forEach(dx=>b(x+dx,.5,z,.18,1,1.1,'#b29acb'));\n          [-.95,.95].forEach((dx,i)=>{this.person(x+dx,z+.9,i?color:'#a89ac5');b(x+dx,1.26,z,.65,.3,.08,'#74749a');});\n          b(x,1.13,z-.3,.6,.04,.45,'#fff9e8');\n        }else{this.desk(x-1.45,z-.2,color);this.desk(x+1.3,z-.2,color);this.person(x-1.45,z+.78,color);this.person(x+1.3,z+.78,'#b59cdd');}\n        this.plant(x+2.65,z-2.12,.85);\n        b(x-2.65,1.1,z-2.2,.65,2.2,.65,'#d6bb91');\n        for(let r=0;r<3;r++){b(x-2.65,.35+r*.62,z-1.84,.58,.06,.08,'#f5debb');for(let c=0;c<3;c++)b(x-2.85+c*.19,.55+r*.62,z-1.98,.12,.35,.26,[color,'#efdbb7','#a99bc8'][c]);}\n        b(x, .38,z+2.7,5,.75,.08,'#d7d5ed');b(x,.82,z+2.7,5,.07,.14,'#af9acb');\n      });\n      [-10,10].forEach(x=>[0,7.8].forEach(z=>this.plant(x,z,1)));\n      b(-6,.45,7.7,2.9,.85,1,'#bca0e0');b(-6,.95,8.1,2.9,.7,.22,'#a48acd');b(-6,.63,7.6,2.6,.2,.85,'#d7c6f0');\n      b(-3.9,.4,7.5,.9,.8,.9,'#e7cfa9');b(-3.9,.85,7.5,.6,.1,.6,'#faf3e3');\n      b(6,.72,7.8,3.3,1.45,1,'#d0b9e6');b(6,1.5,7.8,3.5,.15,1.2,'#ede5f4');b(6,1.8,7.6,.7,.5,.1,'#8072aa');\n      this.plant(8.7,7.6,.9);this.person(2.7,7.7,'#9f81db',true);\n      this.boxes.sort((a,b)=>a.layer-b.layer||this.depth(a)-this.depth(b));\n    }\n    depth(o){return o.x*.36+o.z*.93+o.y*.3;}\n    project(x,y,z){return {x:this.ox+(x*.933-z*.36)*this.scale,y:this.oy+(x*.36+z*.933)*.49*this.scale-y*.872*this.scale};}\n    polygon(points,fill,stroke){const c=this.ctx;c.beginPath();points.forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.closePath();c.fillStyle=fill;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=1.5;c.stroke();}}\n    resize(){const width=this.host.clientWidth,height=this.host.clientHeight;if(!width||!height)return;this.width=width;this.height=height;const ratio=Math.min(window.devicePixelRatio||1,2);this.canvas.width=Math.round(width*ratio);this.canvas.height=Math.round(height*ratio);this.canvas.style.width=width+'px';this.canvas.style.height=height+'px';this.ctx.setTransform(ratio,0,0,ratio,0,0);this.scale=Math.min(width/29,height/15.3);this.ox=width/2+.4*this.scale;this.oy=height/2+.4*this.scale;this.draw();}\n    draw(){\n      if(!this.width)return;const c=this.ctx;c.clearRect(0,0,this.width,this.height);\n      const ground=[[-11,-9],[11,-9],[11,10],[-11,10]].map(([x,z])=>this.project(x,-.7,z));c.save();c.shadowColor='#55408040';c.shadowBlur=24;this.polygon(ground,'#e4dcf2');c.restore();\n      this.boxes.forEach(o=>{\n        const x=o.x-o.w/2,X=o.x+o.w/2,z=o.z-o.d/2,Z=o.z+o.d/2,y=o.y-o.h/2,Y=o.y+o.h/2;\n        let color=o.color;if(o.room&&(o.room===this.selected||o.room===this.hover))color='#c4a4f4';\n        this.polygon([[X,y,z],[X,y,Z],[X,Y,Z],[X,Y,z]].map(p=>this.project(...p)),tint(color,.83));\n        this.polygon([[x,y,Z],[X,y,Z],[X,Y,Z],[x,Y,Z]].map(p=>this.project(...p)),tint(color,.94));\n        this.polygon([[x,Y,z],[X,Y,z],[X,Y,Z],[x,Y,Z]].map(p=>this.project(...p)),tint(color,1.04));\n      });\n      ROOMS.forEach((r,i)=>{const p=this.project(r.x,3.6,r.z-2.3),button=this.buttons[i];button.style.left=p.x+'px';button.style.top=p.y+'px';button.classList.toggle('selected',this.selected===r.id);});\n    }\n    hit(x,y){\n      for(const room of [...ROOMS].reverse()){\n        const poly=[[-3.15,-2.9],[3.15,-2.9],[3.15,2.9],[-3.15,2.9]].map(([dx,dz])=>this.project(room.x+dx,.2,room.z+dz));\n        let inside=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if(((a.y>y)!==(b.y>y))&&x<(b.x-a.x)*(y-a.y)/(b.y-a.y)+a.x)inside=!inside;}if(inside)return room.id;\n      }return null;\n    }\n    select(id){this.selected=id;this.buttons.forEach(b=>b.setAttribute('aria-expanded',String(b.dataset.voxelRoom===id)));this.draw();}\n    destroy(){this.observer?.disconnect();this.canvas.removeEventListener('pointermove',this.pointer);this.canvas.removeEventListener('pointerleave',this.leave);this.canvas.removeEventListener('click',this.click);this.canvas.remove();this.labels.remove();}\n  }\n  window.VoxelOffice=VoxelOffice;\n})();\n";
